begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email) values
 ('81000000-0000-4000-8000-000000000001','receipt-a@example.invalid'),
 ('81000000-0000-4000-8000-000000000002','receipt-b@example.invalid'),
 ('81000000-0000-4000-8000-000000000003','receipt-c@example.invalid');
create temporary table commands(name text primary key, result jsonb);
grant all on commands to authenticated;
set local role authenticated;
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
insert into commands values('loan',public.create_loan('LENDER',1000,'VND','2026-09-01','2026-10-01',null,null,'82000000-0000-4000-8000-000000000001'));
select throws_ok($$select public.create_loan('LENDER',2000,'VND','2026-09-01','2026-10-01',null,null,'82000000-0000-4000-8000-000000000001')$$,'P0001','IDEMPOTENCY_PAYLOAD_MISMATCH','Create key cannot silently change amount');
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000002';
select lives_ok($$select public.accept_loan_invite((select result->>'invite_token' from commands where name='loan'),'82000000-0000-4000-8000-000000000002')$$,'Counterparty joins');
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select is(public.create_loan('LENDER',1000,'VND','2026-09-01','2026-10-01',null,null,'82000000-0000-4000-8000-000000000001')->>'invite_token',null::text,'Cached create no longer returns a consumed invite token');
insert into commands values('partial',public.submit_repayment((select (result->>'loan_id')::uuid from commands where name='loan'),100,'2026-09-02',null,null,'82000000-0000-4000-8000-000000000003'));
select is(public.submit_repayment((select (result->>'loan_id')::uuid from commands where name='loan'),100,'2026-09-02',null,null,'82000000-0000-4000-8000-000000000003'),(select result from commands where name='partial'),'Same command retry returns the same receipt');
select throws_ok($$select public.submit_repayment((select (result->>'loan_id')::uuid from commands where name='loan'),200,'2026-09-02',null,null,'82000000-0000-4000-8000-000000000003')$$,'P0001','IDEMPOTENCY_PAYLOAD_MISMATCH','Changed repayment amount with same key is rejected');
select is((select count(*) from public.repayments where loan_id=(select (result->>'loan_id')::uuid from commands where name='loan')),1::bigint,'Retries/conflicts create no extra repayment');
insert into commands values('full',public.submit_repayment((select (result->>'loan_id')::uuid from commands where name='loan'),1000,'2026-09-02',null,null,'82000000-0000-4000-8000-000000000004'));
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000002';
select lives_ok($$select public.confirm_repayment((select (result->>'repayment_id')::uuid from commands where name='full'),'82000000-0000-4000-8000-000000000005')$$,'Confirm in full succeeds');
select is(public.get_loan_room((select (result->>'loan_id')::uuid from commands where name='loan'))->>'balance_minor','0','Balance is zero');
select is((select status::text from public.repayments where id=(select (result->>'repayment_id')::uuid from commands where name='partial')),'CANCELLED','Settlement cancels other pending proposals');
select is((select count(*) from public.loan_events where entity_id=(select (result->>'repayment_id')::uuid from commands where name='partial') and event_type='REPAYMENT_CANCELLED' and metadata->>'reason'='LOAN_REPAID'),1::bigint,'Automatic cancellation has an explicit audit reason');
select lives_ok($$select public.confirm_repayment((select (result->>'repayment_id')::uuid from commands where name='full'),'82000000-0000-4000-8000-000000000005')$$,'Confirmation retry returns its receipt after settlement');
select is((select count(*) from public.loan_events where entity_id=(select (result->>'repayment_id')::uuid from commands where name='full') and event_type='REPAYMENT_CONFIRMED'),1::bigint,'No duplicate confirm event');
select throws_ok($$select public.confirm_repayment((select (result->>'repayment_id')::uuid from commands where name='partial'),'82000000-0000-4000-8000-000000000006')$$,'P0001','REPAYMENT_NOT_PENDING','Cancelled proposal cannot be confirmed after settlement');
reset role;
update public.loan_members set user_id=null where user_id='81000000-0000-4000-8000-000000000001';
set local role authenticated;
set local request.jwt.claim.sub='81000000-0000-4000-8000-000000000001';
select throws_ok($$select public.submit_repayment((select (result->>'loan_id')::uuid from commands where name='loan'),100,'2026-09-02',null,null,'82000000-0000-4000-8000-000000000003')$$,'42501',null,'Revoked member cannot retrieve cached command response');
reset role;
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('create_loan','accept_loan_invite','decline_loan_invite','submit_repayment','confirm_repayment','get_my_loans','get_loan_room','get_loan_repayments','get_loan_invite_preview') and has_function_privilege('anon',p.oid,'execute')),'Anonymous role cannot execute authenticated application RPCs');
select ok(not has_function_privilege('authenticated','private.begin_idempotent_command(text,uuid,jsonb)','execute'),'Authenticated caller cannot invoke receipt helper directly');
select * from finish();
rollback;
